/**
 * Describes the browser and GPU as the browser reports them, which a
 * replaced user agent string doesn't show.
 *
 * @returns Lines of "Name: value" text.
 */
export async function describeSystem() {
    const { userAgentData, gpu } = navigator;
    const lines = [];
    if (userAgentData) {
        const { fullVersionList, platformVersion, architecture } = await userAgentData.getHighEntropyValues([
            "fullVersionList",
            "platformVersion",
            "architecture",
        ]);
        const brands = (fullVersionList ?? [])
            .filter(({ brand }) => !/not.a.brand/i.test(brand))
            .map(({ brand, version }) => `${brand} ${version}`);
        lines.push(`Browser: ${brands.join(", ")}`);
        lines.push(`OS: ${userAgentData.platform} ${platformVersion ?? ""} ${architecture ?? ""}`.trimEnd());
    }
    if (!gpu) {
        lines.push("WebGPU adapter: navigator.gpu is missing");
    }
    else {
        const adapter = await gpu.requestAdapter();
        if (!adapter) {
            lines.push("WebGPU adapter: none");
        }
        else {
            const { vendor, architecture, description, isFallbackAdapter } = adapter.info;
            const fallback = isFallbackAdapter ? " (fallback adapter)" : "";
            lines.push(`WebGPU adapter: ${[vendor, architecture, description].filter(Boolean).join(" ")}${fallback}`);
        }
    }
    return lines.join("\n");
}
